import numpy as np

def select_item(current_index, remaining_capacity, weights, values, num_items):
    if current_index >= num_items:
        return 0
    if weights[current_index] > remaining_capacity:
        return 0

    # 初始化记忆结构（全局模拟）
    if not hasattr(select_item, 'success_history'):
        select_item.success_history = []
    if not hasattr(select_item, 'avg_density'):
        select_item.avg_density = 0.0
    if not hasattr(select_item, 'count'):
        select_item.count = 0

    # 更新平均密度（所有已决策物品）
    select_item.count += 1
    if weights[current_index] <= remaining_capacity:
        select_item.avg_density = (select_item.avg_density * (select_item.count - 1) + values[current_index] / max(weights[current_index], 1e-6)) / select_item.count

    # 计算未来潜在价值：基于剩余容量和未决策物品的平均密度
    future_items = np.arange(current_index + 1, num_items)
    if len(future_items) > 0:
        future_weights = weights[future_items]
        future_values = values[future_items]
        feasible = future_weights <= remaining_capacity
        if np.any(feasible):
            future_density = np.divide(future_values[feasible], future_weights[feasible], out=np.zeros_like(future_values[feasible], dtype=float), where=future_weights[feasible]!=0)
            future_avg_density = np.mean(future_density) if len(future_density) > 0 else 0
        else:
            future_avg_density = 0
    else:
        future_avg_density = 0

    # 当前物品密度
    current_density = values[current_index] / max(weights[current_index], 1e-6)

    # 历史成功模式：如果过去拿取密度相近的物品效果好，则提高取的概率
    success_bias = 0.0
    if len(select_item.success_history) > 0:
        recent_success = select_item.success_history[-min(10, len(select_item.success_history)):]
        if len(recent_success) > 0:
            avg_success_density = np.mean(recent_success)
            if current_density >= avg_success_density * 0.9:
                success_bias = 0.15

    # 适应性阈值：基于未来潜力与当前密度对比
    if future_avg_density > current_density * 1.1:
        # 未来有更高价值物品，降低当前拿取概率
        threshold = 0.4
    elif future_avg_density < current_density * 0.7:
        # 当前物品明显优于未来，提高拿取概率
        threshold = 0.7
    else:
        # 均衡情况，考虑容量紧张度
        capacity_ratio = remaining_capacity / (np.sum(weights[current_index:]) + 1e-6)
        threshold = 0.5 + 0.2 * (1 - capacity_ratio)  # 容量紧张时更保守

    # 加入历史成功模式的偏置
    threshold = min(0.9, threshold + success_bias)

    # 回溯奖励：如果之前因容量不足跳过但当前容量足够，考虑补偿
    if not hasattr(select_item, 'skipped'):
        select_item.skipped = set()
    if current_index in select_item.skipped and weights[current_index] <= remaining_capacity:
        threshold += 0.2
        select_item.skipped.discard(current_index)

    # 决策
    if np.random.rand() < threshold:
        # 记录成功模式（当前密度）
        select_item.success_history.append(current_density)
        return 1
    else:
        # 记录跳过，便于将来回溯
        select_item.skipped.add(current_index)
        return 0
